typedef struct { int left, right; long val; } Node;
long global_max = LONG_MIN;

long dfs(Node tree[], int idx) {
    if (idx == -1) return 0;
    long left = MAX(dfs(tree, tree[idx].left), 0);
    long right = MAX(dfs(tree, tree[idx].right), 0);
    long current_path = tree[idx].val + left + right;
    if (current_path > global_max) global_max = current_path;
    return tree[idx].val + MAX(left, right);
}

