import java.util.*;

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int x) { val = x; }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();
        if (line.equals("[]") || line.isEmpty()) {
            System.out.println("[]");
            return;
        }

        String content = line.substring(1, line.length() - 1).trim();
        if (content.isEmpty()) {
            System.out.println("[]");
            return;
        }
        String[] parts = content.split(",");
        TreeNode root = deserialize(parts);
        System.out.println(serialize(root));
    }

    public static TreeNode deserialize(String[] parts) {
        if (parts.length == 0 || parts[0].trim().equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < parts.length) {
            TreeNode node = q.poll();
            if (i < parts.length && !parts[i].trim().equals("null")) {
                node.left = new TreeNode(Integer.parseInt(parts[i].trim()));
                q.add(node.left);
            }
            i++;
            if (i < parts.length && !parts[i].trim().equals("null")) {
                node.right = new TreeNode(Integer.parseInt(parts[i].trim()));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static String serialize(TreeNode root) {
        if (root == null) return "[]";
        List<String> res = new ArrayList<>();
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) {
            TreeNode node = q.poll();
            if (node == null) {
                res.add("null");
            } else {
                res.add(String.valueOf(node.val));
                q.add(node.left);
                q.add(node.right);
            }
        }
        while (!res.isEmpty() && res.get(res.size() - 1).equals("null")) res.remove(res.size() - 1);
        return "[" + String.join(", ", res) + "]";
    }
}

import sys
import json
from collections import deque

class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree(preorder, inorder):
    index_map = {value: i for i, value in enumerate(inorder)}
    preorder_index = 0

    def build(left, right):
        nonlocal preorder_index
        if left > right:
            return None
        root_value = preorder[preorder_index]
        preorder_index += 1
        root = TreeNode(root_value)
        middle = index_map[root_value]
        root.left = build(left, middle - 1)
        root.right = build(middle + 1, right)
        return root

    return build(0, len(inorder) - 1)

def serialize(root):
    if root is None:
        return []
    result = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            result.append(None)
        else:
            result.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
    while result and result[-1] is None:
        result.pop()
    return result

def main():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    lines = input_data.splitlines()
    if len(lines) >= 2:
        preorder = json.loads(lines[0].strip())
        inorder = json.loads(lines[1].strip())
    else:
        line = input_data.strip()
        split = line.find("]") + 1
        preorder = json.loads(line[:split].strip())
        inorder = json.loads(line[split:].strip())

    root = build_tree(preorder, inorder)
    print(json.dumps(serialize(root)))

