import java.util.*;

class Solution {
    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int val) { this.val = val; }
    }

    static int preorderIndex;
    static Map<Integer, Integer> inorderMap;

    static TreeNode buildTree(int[] preorder, int left, int right) {
        if (left > right) return null;
        int value = preorder[preorderIndex++];
        TreeNode root = new TreeNode(value);
        int middle = inorderMap.get(value);
        root.left = buildTree(preorder, left, middle - 1);
        root.right = buildTree(preorder, middle + 1, right);
        return root;
    }

    static int[] parseArray(String input) {
        input = input.trim();
        if (input.equals("[]")) return new int[0];
        String content = input.substring(1, input.length() - 1).trim();
        if (content.isEmpty()) return new int[0];
        String[] parts = content.split(",");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++)
            result[i] = Integer.parseInt(parts[i].trim());
        return result;
    }

    static String serialize(TreeNode root) {
        if (root == null) return "[]";
        List<String> result = new ArrayList<>();
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node == null) {
                result.add("null");
            } else {
                result.add(String.valueOf(node.val));
                queue.offer(node.left);
                queue.offer(node.right);
            }
        }

        while (!result.isEmpty() && result.get(result.size() - 1).equals("null"))
            result.remove(result.size() - 1);

        StringBuilder output = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) output.append(", ");
            output.append(result.get(i));
        }
        output.append("]");
        return output.toString();
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextLine()) return;

        String first = scanner.nextLine().trim();
        String second;

        if (scanner.hasNextLine()) {
            second = scanner.nextLine().trim();
        } else {
            int split = first.indexOf("]") + 1;
            second = first.substring(split).trim();
            first = first.substring(0, split).trim();
        }

        int[] preorder = parseArray(first);
        int[] inorder = parseArray(second);

        inorderMap = new HashMap<>();
        preorderIndex = 0;

        for (int i = 0; i < inorder.length; i++)
            inorderMap.put(inorder[i], i);

        TreeNode root = buildTree(preorder, 0, inorder.length - 1);
        System.out.println(serialize(root));
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

int preorder[10000], inorder[10000];
int preorderSize = 0, inorderSize = 0, preorderIndex = 0;

TreeNode* createNode(int value) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->val = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void parseArray(const char* input, int* array, int* size) {
    *size = 0;
    const char* p = input;
    while (*p) {
        if (*p == '-' || (*p >= '0' && *p <= '9')) {
            char* end;
            long value = strtol(p, &end, 10);
            array[(*size)++] = (int)value;
            p = end;
        } else {
            p++;
        }
    }
}

int findInorderIndex(int value, int left, int right) {
    for (int i = left; i <= right; i++)
        if (inorder[i] == value) return i;
    return -1;
}

TreeNode* buildTree(int left, int right) {
    if (left > right) return NULL;

    int value = preorder[preorderIndex++];
    int middle = findInorderIndex(value, left, right);

    TreeNode* root = createNode(value);
    root->left = buildTree(left, middle - 1);
    root->right = buildTree(middle + 1, right);
    return root;
}

void serialize(TreeNode* root) {
    if (root == NULL) {
        printf("[]");
        return;
    }

    TreeNode* queue[20000];
    int front = 0, rear = 0;
    char output[20000][32];
    int isNull[20000], count = 0;

    queue[rear++] = root;

    while (front < rear) {
        TreeNode* node = queue[front++];

        if (node == NULL) {
            isNull[count] = 1;
            output[count][0] = '\0';
            count++;
        } else {
            isNull[count] = 0;
            sprintf(output[count], "%d", node->val);
            count++;
            queue[rear++] = node->left;
            queue[rear++] = node->right;
        }
    }

    while (count > 0 && isNull[count - 1]) count--;

    printf("[");
    for (int i = 0; i < count; i++) {
        if (i > 0) printf(", ");
        if (isNull[i]) printf("null");
        else printf("%s", output[i]);
    }
    printf("]");
}

