using namespace std;

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int value) : val(value), left(nullptr), right(nullptr) {}
};

vector<int> parseArray(const string& input) {
    vector<int> result;
    for (size_t i = 0; i < input.size();) {
        if (input[i] == '-' || (input[i] >= '0' && input[i] <= '9')) {
            int sign = 1;
            if (input[i] == '-') { sign = -1; i++; }
            int value = 0;
            while (i < input.size() && input[i] >= '0' && input[i] <= '9') {
                value = value * 10 + (input[i] - '0');
                i++;
            }
            result.push_back(sign * value);
        } else {
            i++;
        }
    }
    return result;
}

class Solution {
public:
    unordered_map<int, int> inorderIndex;
    int preorderIndex = 0;

    TreeNode* buildTree(const vector<int>& preorder, int left, int right) {
        if (left > right) return nullptr;

        int value = preorder[preorderIndex++];
        TreeNode* root = new TreeNode(value);
        int middle = inorderIndex[value];

        root->left = buildTree(preorder, left, middle - 1);
        root->right = buildTree(preorder, middle + 1, right);
        return root;
    }

    string serialize(TreeNode* root) {
        if (root == nullptr) return "[]";

        vector<string> result;
        queue<TreeNode*> q;
        q.push(root);

        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();

            if (node == nullptr) {
                result.push_back("null");
            } else {
                result.push_back(to_string(node->val));
                q.push(node->left);
                q.push(node->right);
            }
        }

        while (!result.empty() && result.back() == "null")
            result.pop_back();

        string output = "[";
        for (size_t i = 0; i < result.size(); i++) {
            if (i > 0) output += ", ";
            output += result[i];
        }
        output += "]";
        return output;
    }

    void solve(const vector<int>& preorder, const vector<int>& inorder) {
        inorderIndex.clear();
        preorderIndex = 0;

        for (int i = 0; i < (int)inorder.size(); i++)
            inorderIndex[inorder[i]] = i;

        TreeNode* root = buildTree(
            preorder, 0, (int)inorder.size() - 1
        );

        cout << serialize(root) << '\n';
    }
};

int main() {
    ios::sync_with_stdio(false);
