    if (!getline(cin, first)) return 0;

    if (!getline(cin, second)) {
        size_t split = first.find(']') + 1;
        second = first.substr(split);
        first = first.substr(0, split);
    }

    vector<int> preorder = parseArray(first);
    vector<int> inorder = parseArray(second);

    Solution solution;
    solution.solve(preorder, inorder);
    return 0;
}

