import java.util.*;

public class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean end = false;
    }

    static TrieNode root;

    static void addWord(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) node.children[idx] = new TrieNode();
            node = node.children[idx];
        }
        node.end = true;
    }

    static boolean search(String word) {
        return dfs(word, 0, root);
    }

    static boolean dfs(String word, int i, TrieNode node) {
        if (node == null) return false;
        if (i == word.length()) return node.end;
        char c = word.charAt(i);
        if (c == '.') {
            for (TrieNode child : node.children) {
                if (child != null && dfs(word, i + 1, child)) return true;
            }
            return false;
        }
        return dfs(word, i + 1, node.children[c - 'a']);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String opsLine = sc.nextLine().trim();
        if (!sc.hasNextLine()) return;
        String argsLine = sc.nextLine().trim();

        List<String> ops = parseStringList(opsLine);
        List<List<String>> argsList = parseNestedStringList(argsLine);

        List<String> res = new ArrayList<>();

        for (int i = 0; i < ops.size(); i++) {
            String op = ops.get(i);
            List<String> opArgs = argsList.get(i);

            if (op.equals("WordDictionary")) {
                root = new TrieNode();
                res.add("null");
            } else if (op.equals("addWord")) {
                addWord(opArgs.get(0));
                res.add("null");
            } else if (op.equals("search")) {
                res.add(String.valueOf(search(opArgs.get(0))));
            }
        }
        System.out.println("[" + String.join(", ", res) + "]");
    }

    private static List<String> parseStringList(String s) {
        List<String> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        boolean inQuote = false;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '"') inQuote = !inQuote;
            else if (c == ',' && !inQuote) { res.add(sb.toString().trim()); sb.setLength(0); }
            else sb.append(c);
        }
        if (sb.length() > 0) res.add(sb.toString().trim());
        return res;
    }

    private static List<List<String>> parseNestedStringList(String s) {
        List<List<String>> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        int depth = 0;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '[') { depth++; if (depth > 1) sb.append(c); }
            else if (c == ']') {
                depth--;
                if (depth > 0) sb.append(c);
                else {
                    List<String> sub = new ArrayList<>();
                    String content = sb.toString().trim();
                    if (!content.isEmpty())
                        for (String item : content.split(","))
                            sub.add(item.trim().replace("\"", ""));
                    res.add(sub);
                    sb.setLength(0);
                }
            } else if (c == ',' && depth == 0) { }
            else if (depth > 0) sb.append(c);
        }
        return res;
    }
}

