#define ALPHABET_SIZE 26
#define MAX_WORDS 1000
#define MAX_WORD_LEN 101 // 100 + null terminator

typedef struct TrieNode {
    struct TrieNode* children[ALPHABET_SIZE];
    int count; // Number of words passing through this node
} TrieNode;

TrieNode* createTrieNode() {
    TrieNode* newNode = (TrieNode*)malloc(sizeof(TrieNode));
    if (newNode) {
        newNode->count = 0;
        for (int i = 0; i < ALPHABET_SIZE; i++) {
            newNode->children[i] = NULL;
        }
    }
    return newNode;
}

void insert(TrieNode* root, const char* word) {
    TrieNode* curr = root;
    int len = strlen(word);
    for (int i = 0; i < len; i++) {
        int index = word[i] - 'a';
        if (!curr->children[index]) {
            curr->children[index] = createTrieNode();
        }
        curr = curr->children[index];
        curr->count++;
    }
}

char* findShortestUniquePrefix(TrieNode* root, const char* word) {
    TrieNode* curr = root;
    static char prefix[MAX_WORD_LEN]; // Static buffer for result
    int prefix_len = 0;
    int len = strlen(word);

    for (int i = 0; i < len; i++) {
        int index = word[i] - 'a';
        curr = curr->children[index];
        prefix[prefix_len++] = word[i];
        prefix[prefix_len] = '\0'; // Null-terminate current prefix
        if (curr->count == 1) {
            return strdup(prefix); // Return a dynamically allocated copy
        }
    }
    return strdup(prefix); // Should not be reached if all words have unique prefixes
}

void freeTrie(TrieNode* node) {
    if (!node) return;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        freeTrie(node->children[i]);
    }
    free(node);
}

