        for (int i = 0; i < parts.length; i++) {
            nums[i] = Integer.parseInt(parts[i].trim());
        }

        BinaryTrie trie = new BinaryTrie();
        for (int num : nums) {
            trie.insert(num);
        }

        int maxXorVal = 0;
        for (int num : nums) {
            maxXorVal = Math.max(maxXorVal, trie.findMaxXor(num));
        }

        System.out.println(maxXorVal);
        sc.close();
    }
}

