        if (!sc.hasNextLine()) return;
        String argsLine = sc.nextLine().trim();

        List<String> ops = parseStringList(opsLine);
        List<List<String>> argsList = parseNestedStringList(argsLine);

        List<String> res = new ArrayList<>();

        for (int i = 0; i < ops.size(); i++) {
            String op = ops.get(i);
            List<String> opArgs = argsList.get(i);

            if (op.equals("MapSum")) {
                map = new HashMap<>();
                res.add("null");
            } else if (op.equals("insert")) {
                map.put(opArgs.get(0), Integer.parseInt(opArgs.get(1)));
                res.add("null");
            } else if (op.equals("sum")) {
                String prefix = opArgs.get(0);
                int total = 0;
                for (var e : map.entrySet()) {
                    if (e.getKey().startsWith(prefix)) total += e.getValue();
                }
                res.add(String.valueOf(total));
            }
        }
        System.out.println("[" + String.join(", ", res) + "]");
    }

    private static List<String> parseStringList(String s) {
        List<String> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        boolean inQuote = false;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '"') inQuote = !inQuote;
            else if (c == ',' && !inQuote) { res.add(sb.toString().trim()); sb.setLength(0); }
            else sb.append(c);
        }
        if (sb.length() > 0) res.add(sb.toString().trim());
        return res;
    }

    private static List<List<String>> parseNestedStringList(String s) {
        List<List<String>> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        int depth = 0;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '[') { depth++; if (depth > 1) sb.append(c); }
            else if (c == ']') {
                depth--;
                if (depth > 0) sb.append(c);
                else {
                    List<String> sub = new ArrayList<>();
                    String content = sb.toString().trim();
                    if (!content.isEmpty())
                        for (String item : content.split(","))
                            sub.add(item.trim().replace("\"", ""));
                    res.add(sub);
                    sb.setLength(0);
                }
            } else if (c == ',' && depth == 0) { }
            else if (depth > 0) sb.append(c);
        }
        return res;
    }
}

