public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();
        if (line.equals("[]") || line.isEmpty()) {
            System.out.println("[]");
            return;
        }

        String content = line.substring(1, line.length() - 1).trim();
        if (content.isEmpty()) {
            System.out.println("[]");
            return;
        }
        String[] parts = content.split(",");
        TreeNode root = buildTree(parts);
        root = invertTree(root);
        System.out.println(serialize(root));
    }

    public static TreeNode buildTree(String[] parts) {
        if (parts.length == 0 || parts[0].trim().equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < parts.length) {
            TreeNode node = queue.poll();
            if (i < parts.length) {
                String val = parts[i++].trim();
                if (!val.equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(val));
                    queue.add(node.left);
                }
            }
            if (i < parts.length) {
                String val = parts[i++].trim();
                if (!val.equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(val));
                    queue.add(node.right);
                }
            }
        }
        return root;
    }

    public static TreeNode invertTree(TreeNode root) {
        if (root == null) return null;
        TreeNode temp = root.left;
        root.left = invertTree(root.right);
        root.right = invertTree(temp);
        return root;
    }

    public static String serialize(TreeNode root) {
        if (root == null) return "[]";
        List<String> res = new ArrayList<>();
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node == null) {
                res.add("null");
            } else {
                res.add(String.valueOf(node.val));
                queue.add(node.left);
                queue.add(node.right);
            }
        }
        while (!res.isEmpty() && res.get(res.size() - 1).equals("null")) 
            res.remove(res.size() - 1);

        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < res.size(); i++) {
            sb.append(res.get(i));
            if (i < res.size() - 1) sb.append(", ");
        }
        sb.append("]");
        return sb.toString();
    }
}

