    struct TreeNode* right;
} TreeNode;


TreeNode* createNode(int value) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));

    node->val = value;
    node->left = NULL;
    node->right = NULL;

    return node;
}


void parseArray(
        const char* input,
        int values[],
        int* isNull,
        int* size) {

    *size = 0;

    const char* p = input;

    while (*p) {
        if (*p == '-' ||
            (*p >= '0' && *p <= '9')) {

            char* end;
            long value = strtol(p, &end, 10);

            values[*size] = (int)value;
            isNull[*size] = 0;
            (*size)++;

            p = end;
        } else if (*p == 'n') {
            isNull[*size] = 1;
            values[*size] = 0;
            (*size)++;

            while (*p && *p != ',') {
                p++;
            }
        } else {
            p++;
        }
    }
}


TreeNode* buildTree(
        int values[],
        int isNull[],
        int size) {

    if (size == 0 || isNull[0]) {
        return NULL;
    }

    TreeNode* root = createNode(values[0]);

    TreeNode* queue[10000];
    int front = 0;
    int rear = 0;
    int index = 1;

    queue[rear++] = root;

    while (front < rear && index < size) {
        TreeNode* node = queue[front++];

        if (index < size && !isNull[index]) {
            node->left = createNode(values[index]);
            queue[rear++] = node->left;
        }
        index++;

        if (index < size && !isNull[index]) {
            node->right = createNode(values[index]);
            queue[rear++] = node->right;
        }
        index++;
    }

    return root;
}


int isMirror(
        TreeNode* left,
        TreeNode* right) {

    if (left == NULL && right == NULL) {
        return 1;
    }

    if (left == NULL || right == NULL) {
        return 0;
    }

    if (left->val != right->val) {
        return 0;
    }

    return isMirror(left->left, right->right)
        && isMirror(left->right, right->left);
}


int isSymmetric(TreeNode* root) {
    if (root == NULL) {
        return 1;
    }

    return isMirror(root->left, root->right);
}


