        }

        long target =
                Long.parseLong(
                    scanner.nextLine().trim()
                );

        Integer[] values =
                parseArray(treeLine);

        TreeNode root =
                buildTree(values);

        System.out.println(
                hasPathSum(root, target)
                    ? "true"
                    : "false"
        );
    }
}

